    fun forClass(revision: SrdSpellRevision, spellClass: SrdSpellClass): List<SrdSpellCatalogEntry> =
        entries.filter { it.revision == revision && spellClass in it.classes }

    fun find(revision: SrdSpellRevision, stableId: String): SrdSpellCatalogEntry? =
        entries.firstOrNull { it.revision == revision && it.id == stableId }
}
